const m = $input.first().json.body || {};
const key = String(m.name || "") + "|" + String(m.message || "").trim().toLowerCase();
const store = $getWorkflowStaticData("global");
store.seen = store.seen || [];
let h = 0; for (const ch of key) h = (h * 31 + ch.charCodeAt(0)) | 0;
const id = String(h);
const duplicate = store.seen.includes(id);
if (!duplicate) { store.seen = [...store.seen, id].slice(-500); }
const system = "<private instructions: kept out of this repository>";
const schema = { type: "object", additionalProperties: false,
  required: ["language","message_english","brand","intent","requirement","urgency","hot_score","owner","suggested_reply","next_step","confidence"],
  properties: { language:{type:"string"}, message_english:{type:"string"}, brand:{type:"string"}, intent:{type:"string"}, requirement:{type:"string"},
    urgency:{type:"string",enum:["urgent","high","normal","low"]}, hot_score:{type:"integer"}, owner:{type:"string",enum:["director","telecaller","production","export","none"]},
    suggested_reply:{type:"string"}, next_step:{type:"string"}, confidence:{type:"number"} } };
const user = "From: " + (m.name || "?") + ", " + (m.company || "") + ", " + (m.country || "") + "\nChannel: " + (m.channel || "?") + "\nMessage: " + (m.message || "");
return [{ json: { duplicate, input: m, test_grok_down: !!m.test_grok_down,
  grok: { model: "grok-4.7", temperature: 0, messages: [{ role: "system", content: system }, { role: "user", content: user }],
    response_format: { type: "json_schema", json_schema: { name: "inquiry", strict: true, schema } } },
  claude: { model: "claude-opus-5-5", max_tokens: 4000, output_config: { effort: "low", format: { type: "json_schema", schema } },
    system, messages: [{ role: "user", content: user }] } } }];

const c = $input.first().json.choices?.[0]?.message?.content;
let t; try { t = JSON.parse(c); } catch (e) { throw new Error("Grok answer was not valid JSON"); }
return [{ json: { ticket: t, ai_used: "Grok 4.7 (xAI)", fallback: false } }];

const r = $input.first().json;
if (r.stop_reason === "refusal") throw new Error("Claude declined this message");
const text = (r.content || []).filter(b => b.type === "text").map(b => b.text).join("");
return [{ json: { ticket: JSON.parse(text), ai_used: "Claude Opus 5.5 (backup)", fallback: true,
  grok_error: $('Grok sorts it').first().json.error?.message || "Grok failed" } }];

const { ticket: t, ai_used, fallback, grok_error } = $input.first().json;
const m = $('Prepare and check duplicates').first().json.input;
t.hot_score = Math.max(0, Math.min(10, t.hot_score | 0));
const problems = [];
if (/ (cheapest|best quality|leading) /i.test(t.suggested_reply)) problems.push("banned claim");
if (t.confidence < 0.7) problems.push("low confidence");
if (fallback) problems.push("answered by backup AI");
const due = { urgent: 2, high: 24, normal: 72, low: 168 }[t.urgency] || 72;
const intent = String(t.intent || "").toLowerCase();
const action = /quote|price/.test(intent) ? "Send quote" : /catalog/.test(intent) ? "Send catalogue" : /sample/.test(intent) ? "Arrange sample" : /custom|design/.test(intent) ? "Custom design brief" : /complain/.test(intent) ? "Resolve complaint" : /order|payment/.test(intent) ? "Process order or payment" : "Follow up";
const cap = (s) => String(s || "").replace(/^./, (x) => x.toUpperCase());
const values = {
  "color_mm9cpd1j": { label: cap(t.urgency) }, "color_mm9c1s94": { label: action }, "color_mm9c54h3": { label: t.owner },
  "color_mm9c38n": { label: m.channel || "WhatsApp" }, "color_mm9c3svj": { label: t.brand }, "color_mm9ck3pv": { label: t.language },
  "text_mm9cnab6": m.country || "", "numeric_mm9cw74a": String(t.hot_score), "numeric_mm9cp5p1": String(due),
  "text_mm9c5emj": String(t.requirement).slice(0, 250), "text_mm9cv10y": String(t.next_step).slice(0, 250) };
const esc = (x) => String(x || "").replace(/&/g, "&amp;").replace(/</g, "&lt;");
const body = "<p><b>Message (" + esc(m.channel || "web") + ")</b><br>" + esc(m.message) + "</p><p><b>In English</b><br>" + esc(t.message_english) + "</p><p><b>Reply to send (" + esc(t.language) + "), waiting for approval</b><br>" + esc(t.suggested_reply) + "</p><p><b>Next step</b><br>" + esc(t.next_step) + "</p><p>Processed by " + esc(ai_used) + " via n8n</p>";
return [{ json: { result: { ...t, act_within_hours: due, action, ai_used, fallback, grok_error, status: problems.length ? "needs_human_review" : "ready_for_approval", problems },
  monday: { query: "mutation ($b: ID!, $n: String!, $v: JSON!, $body: String!) { create_item(board_id: $b, item_name: $n, column_values: $v, create_labels_if_missing: true) { id } }",
    variables: { b: "<monday-board-id>", n: action + " · " + (m.company || m.name || "New buyer"), v: JSON.stringify(values), body } } } }];
